export const MYTH_ARTICLES: MythArticle[] = [
  { id: 'm1', myth: 'Tantra is synonymous with black magic.', truth: 'Tantra, in its authentic tradition, is a sophisticated spiritual technology of transformation — encompassing mantra, yantra, mudra, nyasa, and visualization. The association with "black magic" comes from a tiny fraction of shatkarma practices (shantik, vashikaran, stambhan, etc.) that are explicitly restricted to initiated adepts under a guru\'s supervision. The vast majority of Tantric practice is devotional and meditative, aimed at the recognition of the divine as one\'s own Self. Conflating Tantra with black magic is a colonial-era misreading that persists in popular culture.', category: 'Tantra', sources: ['Vijnana Bhairava Tantra', 'Tantraloka (Abhinavagupta)', 'Woodroffe, "Shakti and Shakta"'] },
  { id: 'm2', myth: 'Diksha (initiation) is mandatory for all forms of prayer and japa.', truth: 'Diksha is required specifically for Bija Mantra sadhana (seed-syllable mantras like Krim, Hlim, Hum) and for nyasa, chakra, and shatkarma practices. However, Nama Japa (repeating the divine name, e.g., "Om Namah Shivaya," "Hare Krishna," "Om Namo Narayanaya"), the recitation of stotrams (Hanuman Chalisa, Vishnu Sahasranama), and devotional reading of the Puranas require NO initiation. The distinction is between mantras that activate specific energy currents (which need a guru\'s transmission) and mantras that are expressions of devotion (which are open to all).', category: 'Diksha', sources: ['Narada Bhakti Sutras', 'Mantra Mahodadhi', 'Kularnava Tantra'] },
  { id: 'm3', myth: 'Kundalini awakening is dangerous and should be avoided.', truth: 'Kundalini is the dormant spiritual energy at the base of the spine. Spontaneous, unguided awakening can cause physical and psychological disturbance (sometimes called "spiritual emergency"). However, under proper guidance, with adequate preparation (purification of the nadis, strengthening of the nervous system, and emotional grounding), kundalini practices are safe and transformative. The key is preparation and supervision, not avoidance. Bandha, mudra, and pranayama practices that work with kundalini should be learned from a qualified teacher, not from books or videos.', category: 'Kundalini', sources: ['Shiva Sutras', 'Hatha Yoga Pradipika', 'Lee Sannella, "The Kundalini Experience"'] },
  { id: 'm4', myth: 'Shakta and Vaishnava practitioners must follow opposite food rules.', truth: 'While Shakta Tantric traditions may include pancha makara (the "five Ms") in their highest esoteric rituals — strictly under Diksha and not for householders — the day-to-day dietary rules for both traditions emphasize sattvic food. Vaishnava practice emphasizes pure vegetarian food offered to the deity (prasada). Shakta householders likewise eat vegetarian food, with non-vegetarian food reserved for specific festival offerings in certain regional traditions. The notion of a strict, universal "opposite" diet is an oversimplification; both traditions value purity, moderation, and consecration of food.', category: 'Lifestyle', sources: ['Bhagavad Gita 17.7-10', 'Devi Mahatmyam', 'Kularnava Tantra'] },
  { id: 'm5', myth: 'The Sri Chakra is a magical diagram for material gain.', truth: 'The Sri Chakra (Sri Yantra) is a sacred geometric representation of the cosmos and the divine feminine (Lalita Tripura Sundari). While its worship can confer blessings, its true purpose is the recognition of the identity of the individual soul, the universe, and the Devi. The nine interlocking triangles symbolize the union of Shiva (upward) and Shakti (downward), and the journey from the outer gates to the bindu (center) represents the dissolution of the ego into pure consciousness. Treating it as a mere "luck" diagram strips it of its spiritual depth.', category: 'Sri Vidya', sources: ['Soundarya Lahari', 'Tripura Rahasya', 'Bhavanopanishad'] },
];

